module sweet_diet (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] m,\n    input wire [3:0] k,\n    input wire [7:0] a_0,\n    input wire [7:0] a_1,\n    input wire [7:0] a_2,\n    input wire [7:0] a_3,\n    input wire [3:0] b_0,\n    input wire [3:0] b_1,\n    input wire [3:0] b_2,\n    input wire [3:0] b_3,\n    input wire [3:0] b_4,\n    input wire [3:0] b_5,\n    input wire [3:0] b_6,\n    input wire [3:0] b_7,\n    output reg [7:0] result,\n    output reg done,\n    output reg error\n);\n\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] INIT        = 3'd1;\n    localparam [2:0] CHECK       = 3'd2;\n    localparam [2:0] ADD_SWEET   = 3'd3;\n    localparam [2:0] DONE_STATE  = 3'd4;\n    localparam [2:0] FOREVER_ST  = 3'd5;\n\n    reg [2:0] state;\n    reg [7:0] s[0:3];\n    reg [7:0] n;\n    reg [7:0] sum_a;\n    reg [7:0] iteration;\n    reg [7:0] temp_result;\n\n    localparam [7:0] MAX_ITER = 8'd50;\n    integer i;\n    reg [15:0] left_bound, right_bound, mid_value;\n    reg can_add_flag;\n    reg [1:0] add_type;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            for (i = 0; i < 4; i = i + 1) begin\n                s[i] <= 8'd0;\n            end\n            state <= IDLE;\n            result <= 8'd0;\n            done <= 1'b0;\n            error <= 1'b0;\n            n <= 8'd0;\n            sum_a <= 8'd0;\n            iteration <= 8'd0;\n            temp_result <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    error <= 1'b0;\n                    if (start) begin\n                        sum_a <= a_0 + a_1 + a_2 + a_3;\n                        state <= INIT;\n                    end\n                end\n\n                INIT: begin\n                    for (i = 0; i < 4; i = i + 1) begin\n                        s[i] <= 8'd0;\n                    end\n                    n <= {4'd0, k};\n                    \n                    if (k >= 4'd1) s[get_type_idx(b_0)] <= s[get_type_idx(b_0)] + 8'd1;\n                    if (k >= 4'd2) s[get_type_idx(b_1)] <= s[get_type_idx(b_1)] + 8'd1;\n                    if (k >= 4'd3) s[get_type_idx(b_2)] <= s[get_type_idx(b_2)] + 8'd1;\n                    if (k >= 4'd4) s[get_type_idx(b_3)] <= s[get_type_idx(b_3)] + 8'd1;\n                    if (k >= 4'd5) s[get_type_idx(b_4)] <= s[get_type_idx(b_4)] + 8'd1;\n                    if (k >= 4'd6) s[get_type_idx(b_5)] <= s[get_type_idx(b_5)] + 8'd1;\n                    if (k >= 4'd7) s[get_type_idx(b_6)] <= s[get_type_idx(b_6)] + 8'd1;\n                    if (k >= 4'd8) s[get_type_idx(b_7)] <= s[get_type_idx(b_7)] + 8'd1;\n                    
                    state <= CHECK;\n                    iteration <= 8'd0;\n                end\n\n                CHECK: begin\n                    can_add_flag <= 1'b0;\n                    add_type <= 2'd0;\n\n                    for (i = 0; i < 4; i = i + 1) begin\n                        if (i < m) begin\n                            mid_value = (s[i] + 8'd1) * sum_a;\n                            left_bound = n * get_a_val(i);\n                            right_bound = left_bound + sum_a;\n                            left_bound = left_bound - sum_a;\n\n                            if ((mid_value > left_bound) && (mid_value < right_bound)) begin\n                                can_add_flag <= 1'b1;\n                                add_type <= i[1:0];\n                            end\n                        end\n                    end\n\n                    if (can_add_flag) begin\n                        state <= ADD_SWEET;\n                    end else if (iteration >= MAX_ITER) begin\n                        state <= FOREVER_ST;\n                    end else begin\n                        temp_result <= iteration;\n                        state <= DONE_STATE;\n                    end\n                end\n\n                ADD_SWEET: begin\n                    s[add_type] <= s[add_type] + 8'd1;\n                    n <= n + 8'd1;\n                    iteration <= iteration + 8'd1;\n                    state <= CHECK;\n                end\n\n                DONE_STATE: begin\n                    result <= temp_result;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                FOREVER_ST: begin\n                    result <= 8'd255;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\n    function [7:0] get_a_val;\n        input [1:0] type_idx;\n        begin\n            case (type_idx)\n                2'd0: get_a_val = a_0;\n                2'd1: get_a_val = a_1;\n                2'd2: get_a_val = a_2;\n                2'd3: get_a_val = a_3;\n                default: get_a_val = 8'd0;\n            endcase\n        end\n    endfunction\n\n    function [1:0] get_type_idx;\n        input [3:0] b_val;\n        begin\n            if (b_val >= 4'd1 && b_val <= 4'd4) begin\n                get_type_idx = b_val[1:0] - 2'd1;\n            end else begin\n                get_type_idx = 2'd0;\n            end\n        end\n    endfunction\n\nendmodule